export function builtinLibraryDocument(slug: string) {
  return BUILTIN_LIBRARY_DOCUMENTS.find((d) => d.slug === slug) ?? null;
}

export async function readBuiltinLibraryDocument(slug: string) {
  const doc = builtinLibraryDocument(slug);
  if (!doc) return null;
  // slug comes only from the fixed catalog above, never from a user-built path.
  const bytes = await readFile(path.join(process.cwd(), "content", "company-library", `${doc.slug}.pdf`));
  return { bytes: new Uint8Array(bytes), mimeType: "application/pdf", filename: `${doc.slug}.pdf` };
}
